import numpy as np
def equation(eps, T, params):
    a,b,c,d,f,h,j,i,k,m = params[:10]
    num = a + b/T + (c + d/T + f*np.sqrt(T))*eps
    den = 1 + (h + j/T)*eps**2
    return -eps*num/den*np.exp(-(i + k/T + m*np.sqrt(T))*eps)
